        return [row[:] for row in grid]

    def interior(a, b, limit):
        lo = a + 1
        hi = b if b == limit - 1 else b - 1
        return (lo, hi) if lo <= hi else None

    row_inner = [interior(a, b, h) for a, b in rows]
    col_inner = [interior(a, b, w) for a, b in cols]

    colors = {}
    counts = {}
    for i, ri in enumerate(row_inner):
        for j, cj in enumerate(col_inner):
            if ri is None or cj is None:
